import{_ as e,c as s,o as i,ag as l}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Ollama","description":"","frontmatter":{"title":"Ollama"},"headers":[],"relativePath":"general/ollama.md","filePath":"general/ollama.md","lastUpdated":null}'),t={name:"general/ollama.md"};function r(o,a,n,d,p,c){return i(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h1><h2 id="ollama-user-guide" tabindex="-1">Ollama User Guide <a class="header-anchor" href="#ollama-user-guide" aria-label="Permalink to &quot;Ollama User Guide&quot;">​</a></h2><h3 id="introduction-to-ollama" tabindex="-1">Introduction to Ollama <a class="header-anchor" href="#introduction-to-ollama" aria-label="Permalink to &quot;Introduction to Ollama&quot;">​</a></h3><p>Ollama is a command-line tool designed to simplify the management of Docker images and containers. It allows users to efficiently copy, push, and pull Docker images between different environments, such as local development machines, private registries, or public cloud platforms. Ollama is especially useful for developers and system administrators looking to streamline their Docker workflows.</p><p>Network Chuck has made a video to get more advanced: <a href="https://youtu.be/Wjrdr0NU4Sk?si=HcsWZIQD7m_QN091" target="_blank" rel="noreferrer">host ALL your AI locally</a> ## Setting Up Ollama</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before you begin using Ollama, ensure that you have Docker installed on your system. Docker provides the underlying technology that Ollama manipulates. You can download Docker from <a href="https://www.docker.com/products/docker-desktop" target="_blank" rel="noreferrer">the official Docker website</a>.</p><h3 id="installing-ollama" tabindex="-1">Installing Ollama <a class="header-anchor" href="#installing-ollama" aria-label="Permalink to &quot;Installing Ollama&quot;">​</a></h3><p>Currently, Ollama does not have a standalone installation package. Typically, it would be installed via a package manager or directly from its source repository. This guide will assume you have direct access to the Ollama executable.</p><h3 id="setting-up-a-docker-private-registry" tabindex="-1">Setting Up a Docker Private Registry <a class="header-anchor" href="#setting-up-a-docker-private-registry" aria-label="Permalink to &quot;Setting Up a Docker Private Registry&quot;">​</a></h3><p>To test Ollama’s functionality, you can set up a local Docker registry:</p><ul><li><strong>Start the Docker Registry Container:</strong></li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5001:5000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry:2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This command runs a Docker registry as a container, accessible on port 5001 of your localhost.</p><h3 id="using-ollama" tabindex="-1">Using Ollama <a class="header-anchor" href="#using-ollama" aria-label="Permalink to &quot;Using Ollama&quot;">​</a></h3><h3 id="basic-commands" tabindex="-1">Basic Commands <a class="header-anchor" href="#basic-commands" aria-label="Permalink to &quot;Basic Commands&quot;">​</a></h3><ul><li><strong>Copying an Image to a Local Registry:</strong></li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama2:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:5001/ryan/llama2:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This command copies an image named <code>llama2:latest</code> to your local registry under the namespace <code>ryan</code>.</p><ul><li><strong>Pushing an Image:</strong></li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:5001/ryan/llama2:latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --insecure</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This pushes the image to the local registry. The <code>--insecure</code> flag is used because local registries typically do not have HTTPS configured.</p><ul><li><strong>Pulling an Image Back to Ollama:</strong></li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:5001/ryan/llama2:latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --insecure</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This pulls the image from the local registry back to your local machine. ### Executing Commands</p><p>To prompt Ollama, open your command line or terminal:</p><ul><li><p>Navigate to the directory where Ollama is installed if it’s not added to your PATH.</p></li><li><p>Type the <code>ollama</code> command followed by the specific action you want to perform (e.g., <code>cp</code>, <code>push</code>, <code>pull</code>).</p></li><li><p>Include the necessary parameters and flags as shown in the examples above.</p></li></ul><h3 id="advanced-usage" tabindex="-1">Advanced Usage <a class="header-anchor" href="#advanced-usage" aria-label="Permalink to &quot;Advanced Usage&quot;">​</a></h3><ul><li><p><strong>Managing Multiple Registries:</strong> Ollama can handle multiple Docker registries. You can configure Ollama to interact with several registries by specifying different endpoints in the commands.</p></li><li><p><strong>Automating Workflows:</strong> Ollama can be integrated into scripts or CI/CD pipelines to automate the pushing and pulling of Docker images as part of a build process or deployment strategy.</p></li></ul><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><p>For more detailed information on using Ollama and Docker together:</p><ul><li><p><a href="https://docs.docker.com/" target="_blank" rel="noreferrer">Docker Documentation</a></p></li><li><p><a href="https://github.com/ollama/ollama" target="_blank" rel="noreferrer">Ollama Repository</a> (hypothetical link, adjust according to actual source)</p></li><li><p><a href="https://forums.docker.com/" target="_blank" rel="noreferrer">Community Forums and Support</a></p></li></ul><p>This guide provides a quick start to Ollama, helping you set up and begin manipulating Docker images with ease. For more complex scenarios, refer to the full documentation and community resources.</p>',33)])])}const m=e(t,[["render",r]]);export{u as __pageData,m as default};
